REM Sales star schema for Oracle, written as a SQL*Plus script (sqlplus @sales_star.sql).
REM It's a test fixture: the apostrophe in this REM line must not open a string.
SET ECHO OFF
SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE
PROMPT Creating the sales star schema ...

CREATE TABLE sales.dim_customer (
  customer_id    NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1 INCREMENT BY 1),
  customer_name  VARCHAR2(200 CHAR) CONSTRAINT dim_customer_name_nn NOT NULL,
  created_at     TIMESTAMP(6) WITH LOCAL TIME ZONE DEFAULT SYSTIMESTAMP,
  notes          CLOB,
  CONSTRAINT dim_customer_pk PRIMARY KEY (customer_id) USING INDEX TABLESPACE users ENABLE
)
TABLESPACE users
PCTFREE 10
STORAGE (INITIAL 64K NEXT 1M)
NOCOMPRESS LOGGING;

PROMPT Creating DIM_PRODUCT ...
CREATE TABLE sales.dim_product (
  product_id   NUMBER(10) NOT NULL ENABLE,
  product_name VARCHAR2(100 BYTE),
  unit_price   NUMBER(10,2)
)
SEGMENT CREATION IMMEDIATE;

CREATE TABLE sales.dim_date (
  date_key      NUMBER(8) PRIMARY KEY,
  calendar_date DATE NOT NULL
)
ORGANIZATION INDEX;

CREATE TABLE sales.fct_order_line (
  order_id       NUMBER(12) NOT NULL,
  line_number    NUMBER(4) NOT NULL,
  customer_id    NUMBER(10) NOT NULL,
  product_id     NUMBER(10) NOT NULL,
  order_date_key NUMBER(8),
  amount         NUMBER(12,2),
  raw_payload    RAW(16)
)
PARTITION BY RANGE (order_date_key)
( PARTITION p2023 VALUES LESS THAN (20240101),
  PARTITION pmax  VALUES LESS THAN (MAXVALUE) );

ALTER TABLE sales.dim_product
ADD ( CONSTRAINT dim_product_pk PRIMARY KEY (product_id) );

ALTER TABLE sales.fct_order_line
ADD ( CONSTRAINT fct_order_line_pk PRIMARY KEY (order_id, line_number)
    , CONSTRAINT fct_customer_fk FOREIGN KEY (customer_id) REFERENCES sales.dim_customer (customer_id)
    , CONSTRAINT fct_product_fk FOREIGN KEY (product_id) REFERENCES sales.dim_product
    , CONSTRAINT fct_date_fk FOREIGN KEY (order_date_key) REFERENCES sales.dim_date (date_key) ON DELETE SET NULL
    ) ;

COMMENT ON TABLE sales.dim_customer IS 'One row per customer';
COMMENT ON COLUMN sales.dim_customer.customer_name IS 'Name as the customer entered it';
COMMENT ON COLUMN sales.fct_order_line.amount IS 'Line amount in AUD, after discounts';

CREATE OR REPLACE VIEW sales.v_orders AS SELECT * FROM sales.fct_order_line;
COMMENT ON TABLE sales.v_orders IS 'Every order line';

CREATE SEQUENCE sales.order_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;

CREATE OR REPLACE TRIGGER sales.trg_order_line
BEFORE INSERT ON sales.fct_order_line
FOR EACH ROW
BEGIN
  IF :new.order_id IS NULL THEN
    :new.order_id := sales.order_seq.NEXTVAL;
  END IF;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE sales.tmp_scratch (id NUMBER)';
EXCEPTION
  WHEN OTHERS THEN NULL;
END;
/

GRANT SELECT ON sales.v_orders TO reporter;
